{
  "microtasks": [
    {
      "id": 1,
      "description": "Create an outline for the Scope and Limitations section, dividing it into subsections for Scope (participants, variables) and Limitations (sample constraints, temporal constraints).",
      "prerequisites": []
    },
    {
      "id": 2,
      "description": "Draft the scope paragraph detailing the participant demographics, specifically focusing on high school students from the designated partner schools.",
      "prerequisites": [1]
    },
    {
      "id": 3,
      "description": "Draft the scope paragraph defining the specific aspects of peer pressure and risk-taking behavior being measured in this study.",
      "prerequisites": [1]
    },
    {
      "id": 4,
      "description": "Draft the limitation paragraph explaining how restricting the sample to partner schools limits the generalizability of the findings to the broader adolescent population.",
      "prerequisites": [1]
    },
    {
      "id": 5,
      "description": "Draft the limitation paragraph explaining the temporal constraint of not tracking long-term behavioral outcomes beyond the current school year.",
      "prerequisites": [1]
    },
    {
      "id": 6,
      "description": "Draft a paragraph justifying these scope boundaries (e.g., feasibility, resource constraints) and suggesting how future research could address these limitations.",
      "prerequisites": [4, 5]
    },
    {
      "id": 7,
      "description": "Integrate the drafted paragraphs into a single, cohesive Scope and Limitations section with appropriate transitional phrasing.",
      "prerequisites": [2, 3, 4, 5, 6]
    },
    {
      "id": 8,
      "description": "Review and proofread the integrated section for academic tone, clarity, and alignment with the overall research paper guidelines.",
      "prerequisites": [7]
    }
  ]
}
